        return new Sink(createParts ? Rnd249v.CreateDatasetWriter(route, filePath, files, options)
            : Rnd249v.CreateDatasetWriter(route, files, options));
    }

    sealed class Sink(Rnd249v.DatasetWriter writer) : IRandomDatasetSink
    {
        public void Queue(object row) => writer.Queue((Rnd249v)row);
        public void Dispose() => writer.Dispose();
    }
}